pub(super) fn dispatch(
    engine: &Lodestar,
    name: &str,
    args: &Value,
) -> Option<Result<Value, String>> {
    match name {
        "create_task" => Some((|| {
            let task = engine
                .create_task_covering(
                    req_str(args, "goal_id")?,
                    req_str(args, "title")?,
                    opt_str(args, "acceptance").unwrap_or_default().as_str(),
                    optional_string_arg(args, "blocked_by")?,
                    &str_array(args, "also_serves"),
                )
                .map_err(|e| e.to_string())?;
            ok(&task)
        })()),
        "decompose_goal" => Some((|| {
            ok(&engine
                .decompose_goal(req_str(args, "goal_id")?)
                .map_err(|e| e.to_string())?)
        })()),
        "next_task" => Some((|| match engine.next_task().map_err(|e| e.to_string())? {
            Some(t) => {
                let governing = engine
                    .governing_clauses_for_task(&t.id)
                    .map_err(|e| e.to_string())?;
                let owner = t.owner.as_deref().unwrap_or("unclaimed");
                let mut markdown = format!(
                    "**Next task**: `{}`\n\n**{}**\n\n- Goal: `{}`\n- Status: **{}** / Owner: {}\n\n{}",
                    t.id,
                    t.title,
                    t.goal_id,
                    t.status.as_str(),
                    owner,
                    t.acceptance
                );
                markdown.push_str(&render_governing(&governing));
                let mut structured = serde_json::to_value(&t).map_err(|e| e.to_string())?;
                if let Some(obj) = structured.as_object_mut() {
                    obj.insert(
                        "governing".to_string(),
                        serde_json::to_value(&governing).map_err(|e| e.to_string())?,
                    );
                }
                rendered(markdown, &structured)
            }
            None => text("no claimable task".to_string()),
        })()),
        "claim_task" => Some((|| {
            let task_id = req_str(args, "task_id")?;
            let scope = TaskScope {
                paths: str_array(args, "paths"),
                symbols: str_array(args, "symbols"),
            };
            let won = engine
                .claim_task_with_scope(
                    task_id,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    i64_arg(args, "lease_secs", 300),
                    &scope,
                )
                .map_err(|e| e.to_string())?;
            // On a won claim, surface what governs the work so the agent sees it
            // on pickup without a separate advise call (ADR-0029).
            let governing = if won {
                engine
                    .governing_clauses_for_task(task_id)
                    .map_err(|e| e.to_string())?
            } else {
                Vec::new()
            };
            let mut response = json!({ "won": won, "governing": governing });
            attach_waiting(engine, args, &mut response)?;
            ok(&response)
        })()),
        "task_scope" => Some((|| {
            ok(&engine
                .task_scope(req_str(args, "task_id")?)
                .map_err(|e| e.to_string())?)
        })()),
        "check_overlap" => Some((|| {
            let scope = TaskScope {
                paths: str_array(args, "paths"),
                symbols: str_array(args, "symbols"),
            };
            let overlaps = engine
                .check_claim_overlap(&scope, opt_str(args, "exclude_task_id").as_deref())
                .map_err(|e| e.to_string())?;
            ok(&json!({ "claims": overlaps }))
        })()),
        "renew_lease" => Some((|| {
            let renewed = engine
                .renew_lease(
                    req_str(args, "task_id")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    i64_arg(args, "lease_secs", 300),
                )
                .map_err(|e| e.to_string())?;
            let mut response = json!({ "renewed": renewed });
            attach_waiting(engine, args, &mut response)?;
            ok(&response)
        })()),
        "complete_task" => Some((|| {
            let evidence = parse_evidence(args)?;
            let check = serde_json::from_value(
                args.get("check")
                    .cloned()
                    .ok_or_else(|| "missing required object arg: check".to_string())?,
            )
            .map_err(|error| format!("invalid conformance check: {error}"))?;
            let (completed, conformance) = engine
                .complete_task(
                    req_str(args, "task_id")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    &evidence,
                    &check,
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "completed": completed, "conformance": conformance }))
        })()),
        "release_task" => Some((|| {
            let released = engine
                .release_task(
                    req_str(args, "task_id")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "released": released }))
        })()),
        "recover_claim" => Some((|| {
            let recovered = engine
                .recover_claim(
                    req_str(args, "task_id")?,
                    req_str(args, "expected_owner")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    req_str(args, "reason")?,
                    i64_arg(args, "lease_secs", 300),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "recovered": recovered }))
        })()),
        "claim_transfer_history" => Some((|| {
            ok(&engine
                .claim_transfer_history(req_str(args, "task_id")?)
                .map_err(|e| e.to_string())?)
        })()),
        "block_task" => Some((|| {
            let blocked = engine
                .block_task(
                    req_str(args, "task_id")?,
                    optional_string_arg(args, "blocked_by")?,
                    opt_str(args, "reason").as_deref(),
                    opt_str(args, "actor")
                        .unwrap_or_else(|| "human".to_string())
                        .as_str(),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "blocked": blocked }))
        })()),
        "reopen_task" => Some((|| {
            let reopened = engine
                .reopen_task(req_str(args, "task_id")?)
                .map_err(|e| e.to_string())?;
            ok(&json!({ "reopened": reopened }))
        })()),
        "abandon_task" => Some((|| {
            let abandoned = engine
                .abandon_task(req_str(args, "task_id")?)
                .map_err(|e| e.to_string())?;
            ok(&json!({ "abandoned": abandoned }))
        })()),
        "resolve_task" => Some((|| {
            let resolved = engine
                .resolve_task(req_str(args, "task_id")?, req_str(args, "human")?)
                .map_err(|e| e.to_string())?;
            ok(&json!({ "resolved": resolved }))
        })()),
        "ask_question" => Some((|| {
            let parked = engine
                .ask_question(
                    req_str(args, "task_id")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    req_str(args, "question")?,
                    opt_str(args, "audience").as_deref(),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "needs_input": parked }))
        })()),
        "pending_questions" => Some((|| {
            ok(&engine
                .pending_questions(opt_str(args, "agent").unwrap_or_default().as_str())
                .map_err(|e| e.to_string())?)
        })()),
        "questions_for_a_human" => Some((|| {
            let questions = engine.questions_for_a_human().map_err(|e| e.to_string())?;
            rendered(render_human_questions(&questions), &questions)
        })()),
        "answer" => Some((|| {
            let answered = engine
                .answer_question(
                    req_str(args, "task_id")?,
                    req_str(args, "answer")?,
                    opt_str(args, "author")
                        .unwrap_or_else(|| "human".to_string())
                        .as_str(),
                    i64_arg(args, "lease_secs", 300),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "answered": answered }))
        })()),
        "pause_task" => Some((|| {
            let paused = engine
                .pause_task(
                    req_str(args, "task_id")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    opt_str(args, "reason").as_deref(),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "paused": paused }))
        })()),
        "resume_task" => Some((|| {
            let resumed = engine
                .resume_task(
                    req_str(args, "task_id")?,
                    opt_str(args, "agent").unwrap_or_default().as_str(),
                    i64_arg(args, "lease_secs", 300),
                )
                .map_err(|e| e.to_string())?;
            ok(&json!({ "resumed": resumed }))
        })()),
        "task_qa" => Some((|| {
            ok(&engine
                .task_qa(req_str(args, "task_id")?)
                .map_err(|e| e.to_string())?)
        })()),
        "stalled_work" => Some((|| {
            ok(&engine.stalled_work().map_err(|e| e.to_string())?)
        })()),
        "board" => Some((|| {
            let tasks = engine
                .board(bool_arg(args, "include_terminal", true))
                .map_err(|e| e.to_string())?;
            let mut rows = Vec::with_capacity(tasks.len());
            for task in tasks {
                let scope = engine.task_scope(&task.id).map_err(|e| e.to_string())?;
                let mut row = serde_json::to_value(task).map_err(|e| e.to_string())?;
                row.as_object_mut()
                    .ok_or_else(|| "task did not serialize as an object".to_string())?
                    .insert("scope".to_string(), json!(scope));
                rows.push(row);
            }
            ok(&rows)
        })()),
        _ => None,
    }
}

/// Attach any questions addressed to this agent to a response (ADR-0046).
///
/// Delivered through calls the agent already makes — `claim_task` at pickup and
/// `renew_lease` as the heartbeat — rather than by a new obligation to poll.
/// A capability nobody remembers to call is adopted at the rate we measured for
/// the whole intent plane: zero. The heartbeat is the important one, because a
/// question usually arrives *during* the work rather than before it.
///
/// Absent when nothing is waiting: no key, no empty array, nothing for a caller
/// to interpret. A reader must never have to tell "no questions" apart from
/// "this server does not report questions".
fn attach_waiting(engine: &Lodestar, args: &Value, response: &mut Value) -> Result<(), String> {
    let agent = opt_str(args, "agent").unwrap_or_default();
    if agent.is_empty() {
        return Ok(());
    }
    let waiting = engine
        .pending_questions(&agent)
        .map_err(|e| e.to_string())?;
    if waiting.is_empty() {
        return Ok(());
    }
    if let Some(object) = response.as_object_mut() {
        object.insert(
            "waiting_on_you".to_string(),
            serde_json::to_value(&waiting).map_err(|e| e.to_string())?,
        );
    }
    Ok(())
}

/// The human inbox as readable markdown.
///
/// Rendered rather than dumped as JSON because the reader is a person deciding
/// what to answer, and a wall of objects is not a decision aid. The structured
/// form still travels in `structuredContent` for programmatic callers.
fn render_human_questions(questions: &[HumanQuestion]) -> String {
    if questions.is_empty() {
        return "## Waiting on you\n\nNothing. No agent is parked on a question from you."
            .to_string();
    }
    let mut out = format!("## Waiting on you ({})\n", questions.len());
    for question in questions {
        out.push_str(&format!(
            "\n### {}\n\n{}\n\n- task: `{}`\n- asked by: `{}`\n- waiting: {}\n- reply: `answer` with this task_id\n",
            question.task_title,
            question.question,
            question.task_id,
            question.asked_by,
            humanize_seconds(question.waiting_seconds),
        ));
    }
    out
}

/// A duration a person can read at a glance. Coarse on purpose: the point is
/// "this has been sitting for three days", not a stopwatch.
fn humanize_seconds(seconds: i64) -> String {
    match seconds {
        s if s < 60 => format!("{s}s"),
        s if s < 3_600 => format!("{}m", s / 60),
        s if s < 86_400 => format!("{}h {}m", s / 3_600, (s % 3_600) / 60),
        s => format!("{}d {}h", s / 86_400, (s % 86_400) / 3_600),
    }
}

/// Render the clauses governing a task's scope as a bounded Markdown section for
/// pickup responses (`next_task` / `claim_task`). Empty when nothing governs.
fn render_governing(governing: &[GoverningClause]) -> String {
    if governing.is_empty() {
        return String::new();
    }
    let mut section = String::from("\n\n**Governed by:**");
    for clause in governing {
        section.push_str(&format!(
            "\n- `{}` ({}, {}) — {}",
            clause.goal.id,
            clause.goal.kind.as_str(),
            clause.mode.as_str(),
            clause.goal.title
        ));
    }
    section
}

#[cfg(test)]
mod tests {
    use super::super::call;
    use super::*;
    use lodestar_core::llm::LlmClient;
    use lodestar_core::{now_unix, CodeBindingMode, ConformanceEvidence, GoalKind};
    use mindleak_session::SessionRegistry;

    #[test]
    fn scoped_claim_and_overlap_round_trip_through_tools() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Scoped work", "avoid overlap", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Edit graph", "done").unwrap();
        let task_id = task.id.clone();

        let claimed = call(
            &engine,
            &json!({
                "name": "claim_task",
                "arguments": {
                    "task_id": task_id,
                    "agent": "alice",
                    "lease_secs": 300,
                    "paths": ["crates/mindleak-core/src/**"],
                    "symbols": ["symbol:crates/mindleak-core/src/lib.rs:MindLeak"]
                }
            }),
        )
        .unwrap();
        assert!(claimed["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("true"));

        let overlap = call(
            &engine,
            &json!({
                "name": "check_overlap",
                "arguments": {
                    "paths": ["crates/mindleak-core/src/lib.rs"],
                    "symbols": ["symbol:crates/mindleak-core/src/lib.rs:MindLeak"]
                }
            }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(overlap["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["claims"].as_array().unwrap().len(), 1);
        assert_eq!(body["claims"][0]["owner"], "alice");

        let board = call(
            &engine,
            &json!({
                "name": "board",
                "arguments": { "include_terminal": false }
            }),
        )
        .unwrap();
        let rows: Value =
            serde_json::from_str(board["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(rows[0]["scope"]["paths"][0], "crates/mindleak-core/src/**");
        assert_eq!(
            rows[0]["scope"]["symbols"][0],
            "symbol:crates/mindleak-core/src/lib.rs:MindLeak"
        );
    }

    #[test]
    fn checked_conformance_completes_with_one_authoritative_audit() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship search", "add search", None)
            .unwrap();
        let node_id = "artifact:src/search.rs";
        engine
            .link_goal_to_code(&goal.id, &[node_id.into()], CodeBindingMode::Governed)
            .unwrap();
        let task = engine.create_task(&goal.id, "wire search", "done").unwrap();
        engine.claim_task(&task.id, "agent-a", 300).unwrap();
        let claimed = engine.store().get_task(&task.id).unwrap().unwrap();
        let evidence = json!({
            "schema_version": 1,
            "task_id": task.id,
            "agent_id": "agent-a",
            "started_at": claimed.claim_started_at.unwrap(),
            "ended_at": now_unix(),
            "changed_node_ids": [node_id],
            "failed_node_ids": [],
            "execution_ids": ["execution:proof"],
            "successful_execution_ids": ["execution:proof"],
            "commit_ids": [],
            "summary": "wired search",
            "provenance": [
                {
                    "source_id": "agent:agent-a",
                    "target_id": "execution:proof",
                    "relation": "observed"
                },
                {
                    "source_id": "execution:proof",
                    "target_id": node_id,
                    "relation": "modified"
                }
            ]
        });

        let checked_response = call(
            &engine,
            &json!({
                "name": "check_conformance",
                "arguments": { "task_id": task.id, "evidence": evidence }
            }),
        )
        .unwrap();
        let checked: Value =
            serde_json::from_str(checked_response["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(checked["id"].as_i64().unwrap() > 0);
        assert_eq!(checked["token"].as_str().unwrap().len(), 64);
        assert_eq!(checked["verdict"], "aligned");

        let completed_response = call(
            &engine,
            &json!({
                "name": "complete_task",
                "arguments": {
                    "task_id": task.id,
                    "agent": "agent-a",
                    "evidence": evidence,
                    "check": checked
                }
            }),
        )
        .unwrap();
        let completed: Value =
            serde_json::from_str(completed_response["content"][0]["text"].as_str().unwrap())
                .unwrap();
        assert_eq!(completed["completed"], true);
        assert_eq!(completed["conformance"]["verdict"], "aligned");
        assert_eq!(engine.conformance_history(&task.id).unwrap().len(), 1);
    }

    #[test]
    fn create_task_dispatch_accepts_a_predecessor() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Handoff", "serialize edits", None)
            .unwrap();
        let first = engine.create_task(&goal.id, "First", "done").unwrap();

        let result = call(
            &engine,
            &json!({
                "name": "create_task",
                "arguments": {
                    "goal_id": goal.id,
                    "title": "Second",
                    "acceptance": "done",
                    "blocked_by": first.id
                }
            }),
        )
        .unwrap();
        let task: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();

        assert_eq!(task["status"], "blocked");
        assert!(task["blocked_by"].as_str().unwrap().starts_with("task:"));
    }

    #[test]
    fn decompose_goal_dispatch_falls_back_to_a_single_task_offline() {
        // The decompose_goal tool calls the optional planning model. With no
        // model reachable it must degrade to a single seed task rather than
        // error — and the test must stay deterministic regardless of whatever
        // model a developer happens to be running locally.
        let engine = Lodestar::open_in_memory()
            .unwrap()
            .with_llm(LlmClient::unreachable());
        let goal = engine
            .define_goal(
                GoalKind::Objective,
                "Add search",
                "Implement FTS search",
                None,
            )
            .unwrap();

        let result = call(
            &engine,
            &json!({
                "name": "decompose_goal",
                "arguments": { "goal_id": goal.id }
            }),
        )
        .unwrap();
        let tasks: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();
        let tasks = tasks.as_array().unwrap();
        assert_eq!(tasks.len(), 1);
        assert!(tasks[0]["title"].as_str().unwrap().contains("Add search"));
    }

    #[test]
    fn reopen_task_dispatch_returns_a_manual_hold_to_open() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Recover", "unstick work", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Held", "done").unwrap();
        // A manual hold with no predecessor was previously unrecoverable via the
        // tool surface; reopen_task must return it to a claimable state.
        engine.block_task(&task.id, None, None, "human").unwrap();

        let result = call(
            &engine,
            &json!({ "name": "reopen_task", "arguments": { "task_id": task.id } }),
        )
        .unwrap();
        let payload: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(payload["reopened"], true);

        let board = engine.board(true).unwrap();
        let reopened = board.iter().find(|t| t.id == task.id).unwrap();
        assert_eq!(reopened.status.as_str(), "open");
    }

    #[test]
    fn recover_claim_dispatch_exposes_the_append_only_transfer() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Recover", "transfer legacy work", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "Legacy", "done").unwrap();
        assert!(engine.claim_task(&task.id, "copilot-abcd1234", -1).unwrap());
        let agent = SessionRegistry::new("copilot")
            .unwrap()
            .open_session(
                "00112233445566778899aabbccddeeff",
                mindleak_session::SessionContext::default(),
            )
            .unwrap()
            .agent_id;

        let recovered = call(
            &engine,
            &json!({
                "name": "recover_claim",
                "arguments": {
                    "task_id": task.id,
                    "expected_owner": "copilot-abcd1234",
                    "agent": agent,
                    "reason": "legacy process exited",
                    "lease_secs": 300
                }
            }),
        )
        .unwrap();
        let payload: Value =
            serde_json::from_str(recovered["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(payload["recovered"], true);

        let history = call(
            &engine,
            &json!({
                "name": "claim_transfer_history",
                "arguments": { "task_id": task.id }
            }),
        )
        .unwrap();
        let transfers: Value =
            serde_json::from_str(history["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(transfers.as_array().unwrap().len(), 1);
        assert_eq!(transfers[0]["from_owner"], "copilot-abcd1234");
        assert_eq!(transfers[0]["to_owner"], agent);
    }

    #[test]
    fn resolve_task_dispatch_human_accepts_an_in_review_task() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship auth", "change auth", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "change auth", "done").unwrap();
        engine.claim_task(&task.id, "agent-a", 300).unwrap();
        let started = engine
            .board(true)
            .unwrap()
            .into_iter()
            .find(|t| t.id == task.id)
            .unwrap()
            .claim_started_at
            .unwrap();
        let evidence = ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task.id.clone()),
            agent_id: "agent-a".into(),
            started_at: started,
            ended_at: now_unix(),
            changed_node_ids: Vec::new(),
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: Vec::new(),
            summary: "no mutation evidence".into(),
            provenance: Vec::new(),
        };
        let checked = engine.check_conformance(&evidence, Some(&task.id)).unwrap();
        engine
            .complete_task(&task.id, "agent-a", &evidence, &checked)
            .unwrap();

        // The reviewed agent may not sign off on its own work.
        let denied = call(
            &engine,
            &json!({ "name": "resolve_task", "arguments": { "task_id": task.id, "human": "agent-a" } }),
        );
        assert!(denied.unwrap_err().contains("may not resolve its own"));

        // A distinct human accepts it to done with no conformance re-run.
        let result = call(
            &engine,
            &json!({ "name": "resolve_task", "arguments": { "task_id": task.id, "human": "reviewer" } }),
        )
        .unwrap();
        let payload: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(payload["resolved"], true);

        let board = engine.board(true).unwrap();
        let resolved = board.iter().find(|t| t.id == task.id).unwrap();
        assert_eq!(resolved.status.as_str(), "done");
    }

    #[test]
    fn board_tool_filters_terminal_tasks_when_requested() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "do it", None)
            .unwrap();
        let live = engine.create_task(&goal.id, "Live", "").unwrap();
        let retired = engine.create_task(&goal.id, "Retired", "").unwrap();
        engine.abandon_task(&retired.id).unwrap();

        // Default: every task, including the abandoned one.
        let all: Value = serde_json::from_str(
            call(&engine, &json!({ "name": "board", "arguments": {} })).unwrap()["content"][0]
                ["text"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        assert!(all
            .as_array()
            .unwrap()
            .iter()
            .any(|task| task["id"] == retired.id));

        // Opt into the lean view: terminal tasks drop out, live work remains.
        let active: Value = serde_json::from_str(
            call(
                &engine,
                &json!({ "name": "board", "arguments": { "include_terminal": false } }),
            )
            .unwrap()["content"][0]["text"]
                .as_str()
                .unwrap(),
        )
        .unwrap();
        let ids: Vec<&str> = active
            .as_array()
            .unwrap()
            .iter()
            .map(|task| task["id"].as_str().unwrap())
            .collect();
        assert!(ids.contains(&live.id.as_str()));
        assert!(!ids.contains(&retired.id.as_str()));
    }

    #[test]
    fn create_task_rejects_malformed_predecessor_and_preserves_legacy_calls() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Handoff", "serialize edits", None)
            .unwrap();
        let malformed = json!({
            "name": "create_task",
            "arguments": {
                "goal_id": goal.id,
                "title": "Unsafe",
                "blocked_by": 42
            }
        });
        assert!(call(&engine, &malformed)
            .unwrap_err()
            .contains("must be a string"));

        let legacy = call(
            &engine,
            &json!({
                "name": "create_task",
                "arguments": { "goal_id": goal.id, "title": "Legacy" }
            }),
        )
        .unwrap();
        let task: Value =
            serde_json::from_str(legacy["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(task["status"], "open");
        assert!(task["blocked_by"].is_null());
    }

    // ADR-0046: an addressed question is a durable row a peer must ask for, so
    // a peer who never asks never learns. Delivering it on the calls an agent
    // already makes - pickup and heartbeat - is the difference between a
    // capability and an adopted one; the whole intent plane measured zero
    // adoption while participation was a separate thing to remember.
    #[test]
    fn a_question_addressed_to_you_arrives_on_pickup_and_on_the_heartbeat() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship it", "ship", None)
            .unwrap();
        let theirs = engine.create_task(&goal.id, "their work", "done").unwrap();
        let mine = engine.create_task(&goal.id, "my work", "done").unwrap();

        // agent-b parks its own task on a question addressed to agent-a.
        assert!(engine.claim_task(&theirs.id, "agent-b", 600).unwrap());
        assert!(engine
            .ask_question(&theirs.id, "agent-b", "did you rename it?", Some("agent-a"))
            .unwrap());

        // agent-a picks up unrelated work and is told, without asking.
        let claimed = call(
            &engine,
            &json!({ "name": "claim_task", "arguments": { "task_id": mine.id, "agent": "agent-a" } }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], true);
        assert_eq!(body["waiting_on_you"][0]["task_id"], theirs.id);
        assert_eq!(body["waiting_on_you"][0]["body"], "did you rename it?");

        // The heartbeat matters more than pickup: a question usually arrives
        // during the work, long after the claim.
        let renewed = call(
            &engine,
            &json!({ "name": "renew_lease", "arguments": { "task_id": mine.id, "agent": "agent-a" } }),
        )
        .unwrap();
        let beat: Value =
            serde_json::from_str(renewed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(beat["renewed"], true);
        assert_eq!(beat["waiting_on_you"][0]["task_id"], theirs.id);

        // Nobody asked agent-c anything, so agent-c is told nothing at all -
        // no key, no empty array. "No questions" and "this server does not
        // report questions" must not look the same to a reader.
        let other = engine.create_task(&goal.id, "other work", "done").unwrap();
        let quiet = call(
            &engine,
            &json!({ "name": "claim_task", "arguments": { "task_id": other.id, "agent": "agent-c" } }),
        )
        .unwrap();
        let quiet_body: Value =
            serde_json::from_str(quiet["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(quiet_body.get("waiting_on_you").is_none());

        // Once answered it stops arriving, or the delivery becomes noise the
        // agent learns to skip past.
        assert!(engine
            .answer_question(&theirs.id, "yes, yesterday", "agent-a", 600)
            .unwrap());
        let after = call(
            &engine,
            &json!({ "name": "renew_lease", "arguments": { "task_id": mine.id, "agent": "agent-a" } }),
        )
        .unwrap();
        let after_body: Value =
            serde_json::from_str(after["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(after_body.get("waiting_on_you").is_none());
    }

    #[test]
    fn claim_and_next_task_surface_governing_clauses_on_pickup() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship search", "add search", None)
            .unwrap();
        let node = "artifact:src/search.rs";
        engine
            .link_goal_to_code(&goal.id, &[node.into()], CodeBindingMode::Governed)
            .unwrap();
        let task = engine.create_task(&goal.id, "wire search", "done").unwrap();
        let open_next = engine
            .create_task(&goal.id, "polish search", "done")
            .unwrap();

        // claim_task surfaces what governs the work on a won claim.
        let claimed = call(
            &engine,
            &json!({ "name": "claim_task", "arguments": { "task_id": task.id, "agent": "agent-a" } }),
        )
        .unwrap();
        let body: Value =
            serde_json::from_str(claimed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(body["won"], true);
        assert_eq!(body["governing"][0]["goal"]["id"], goal.id);

        // next_task surfaces the same in structuredContent and the Markdown card.
        let next = call(&engine, &json!({ "name": "next_task", "arguments": {} })).unwrap();
        assert_eq!(next["structuredContent"]["id"], open_next.id);
        assert_eq!(
            next["structuredContent"]["governing"][0]["goal"]["id"],
            goal.id
        );
        assert!(next["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Governed by"));

        // A task whose goal governs no code surfaces an empty list, cleanly.
        let free = engine
            .define_goal(GoalKind::Objective, "Free work", "loose", None)
            .unwrap();
        let ftask = engine.create_task(&free.id, "loose", "x").unwrap();
        let claimed_free = call(
            &engine,
            &json!({ "name": "claim_task", "arguments": { "task_id": ftask.id, "agent": "agent-b" } }),
        )
        .unwrap();
        let free_body: Value =
            serde_json::from_str(claimed_free["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(free_body["won"], true);
        assert!(free_body["governing"].as_array().unwrap().is_empty());
    }
}
